(function(){'use strict';
const api=()=>window.CAGE_BACKEND,app=()=>window.CAGE_APP,$=s=>dialog.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Africa/Blantyre',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const dialog=document.createElement('dialog');dialog.className='qw-dialog';dialog.id='quote-order-dialog';document.body.append(dialog);let data=null,epoch=0,url=null,busy=false;
const canEdit=()=>api()?.moduleLevel('finance')==='edit';
function close(){if(busy)return;epoch++;dialog.close();data=null;if(url)URL.revokeObjectURL(url);url=null;}
for(const event of ['cage:access-closed','cage:session-ready'])window.addEventListener(event,()=>{busy=false;close();dialog.innerHTML='';});
dialog.addEventListener('cancel',e=>{if(busy)e.preventDefault();else close();});
const field=(name,label,type='text',value='',extra='')=>`<label class="field">${esc(label)}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;
function acceptanceFields(po=false){return `<div class="qw-grid">${field('contact','Client contact name','text','','required maxlength="120"')}${field('date','Agreement date','date',today(),'required')}</div><label class="field">Agreed via<select name="method"><option>Phone call</option><option>WhatsApp</option><option>Email</option><option>In person</option></select></label><label class="field">Agreement note<textarea name="note" rows="3" maxlength="3000" placeholder="What was agreed?"></textarea></label>${po?field('clientPoNumber','Client PO number (if supplied)','text','','maxlength="100"'):''}${field('evidence','Supporting evidence (optional)','file','','accept="application/pdf,image/*"')}<label><input type="checkbox" name="confirmed" required> I confirm this client agreed to the ${po?'prepared purchase order':'exact quotation version and amount shown above'}.</label>`;}
function header(){const q=data.quote;return `<div class="dialog-heading"><div><h2>${esc(q.number)} · ${esc(q.client)}</h2><p>${esc(q.currency||'MWK')} ${esc(Number(q.amount).toLocaleString())} · ${esc(q.description)}</p></div><button type="button" data-qw-close>Close</button></div><div class="qw-stage"><span class="complete">Quotation</span><span class="${q.status==='Accepted'?'complete':''}">Acceptance</span><span class="${data.order?.mode?'complete':''}">Order document</span><span class="${data.invoice?'complete':''}">Invoice</span><span class="${data.payments.length?'complete':''}">Payment / receipt</span></div>`;}
function history(){const o=data.order,a=o?.acceptance||data.quote.clientResponse;return `<details class="qw-history"><summary>Document history</summary>${a?`<p>${a.source==='staff'?`Acceptance recorded by ${esc(a.recordedByName)}: ${esc(a.contact)}, ${esc(a.method)}, ${esc(a.date)}`:`Client acceptance: ${esc(a.name)}, ${esc(a.at)}`}<br>${esc(a.note||'')}${a.evidence?` <button data-qw-file="${esc(a.evidence)}">Evidence</button>`:''}</p>`:'<p>No recorded acceptance yet.</p>'}${o?.mode?`<p>${esc(o.mode==='prepared_po'?'CAGE-prepared PO':o.mode==='client_lpo'?'Client LPO':'Order confirmation')}: ${esc(o.order_data.number)}${o.order_data.path?` <button data-qw-file="${esc(o.order_data.path)}">Open original LPO</button>`:''}</p>`:''}${o?.po_approval?`<p>PO approval: ${esc(o.po_approval.contact)}, ${esc(o.po_approval.method)}, ${esc(o.po_approval.date)}. Recorded by ${esc(o.po_approval.recordedByName)}.${o.po_approval.evidence?` <button data-qw-file="${esc(o.po_approval.evidence)}">Evidence</button>`:''}</p>`:''}${data.invoice?`<p>Invoice ${esc(data.invoice.number)} · ${esc(data.invoice.status)}</p>`:''}${data.payments.map(p=>`<p>Payment ${esc(p.paid_on)} · ${esc(p.currency)} ${esc(p.amount)} <button data-qw-receipt="${esc(p.id)}">View receipt</button></p>`).join('')}${data.deliveries.map(d=>`<p>${esc(d.kind==='acceptance'?'Acceptance confirmation':'Order document')} to ${esc(d.recipient)} · ${d.confirmed?'Accepted by email provider':'Delivery not confirmed'} · ${esc(d.created_at.slice(0,10))}</p>`).join('')}</details>`;}
function render(){const q=data.quote,o=data.order;let content='';if(!canEdit()){content='<p class="qw-muted">You have view access. Finance edit access is required to record agreements and prepare invoices.</p>';}
else if(q.status==='Draft'){content='<h3>Send quotation first</h3><p>Review and send this quotation before recording the client’s acceptance. Close this window and choose Send quotation.</p>';}
else if(q.status!=='Accepted'){content=['Declined','Cancelled','Voided','Rejected'].includes(q.status)?'<p>This quotation is closed. Create a new quotation to continue.</p>':`<h3>Record client acceptance</h3><p class="qw-muted">Use this when the client agreed outside the Hub. This records staff evidence, not a response submitted directly by the client.</p><form data-qw-form="accept">${acceptanceFields()}<div class="dialog-actions"><button class="primary-button">Record acceptance</button></div></form>`;}
else if(data.invoice){content=`<h3>Invoice ${esc(data.invoice.number)}</h3><p>${esc(data.invoice.status)} · ${esc(data.invoice.currency||'MWK')} ${esc(data.invoice.amount)}</p><div class="dialog-actions"><button class="primary-button" data-qw-invoice>${data.invoice.status==='Draft'?'Review and send invoice':'View invoice'}</button>${data.invoice.status!=='Paid'?'<button data-qw-pay>Record payment</button>':''}</div>`;}
else if(!o?.mode){content=prepareForm();}
else if(o.mode==='prepared_po'&&!o.po_approval){content=`<h3>Client approval required</h3><p class="qw-muted">The draft PO is prepared by CAGE. Send it for review, then record the client's agreement before creating an invoice.</p><form data-qw-form="approve_po">${acceptanceFields(true)}<div class="dialog-actions"><button class="primary-button">Record PO approval</button></div></form>`;}
else {content=`<h3>Prepare invoice</h3><p class="qw-muted">Client, project, services and amounts will be copied from the accepted quote. Repeating this action opens the same invoice.</p><form data-qw-form="convert"><div class="qw-grid">${field('issued','Invoice date','date',today(),'required')}${field('due','Payment due','date',today(),'required')}</div><button class="primary-button">Create invoice</button></form>`;}
dialog.innerHTML=header()+content+`<p class="qw-error" role="alert"></p><p data-qw-progress role="status"></p><details><summary>Documents and notifications</summary><div class="dialog-actions"><button data-qw-quote>View quotation PDF</button>${o?.mode?'<button data-qw-preview>View order PDF</button>':''}${canEdit()&&q.status==='Accepted'?'<button data-qw-email="acceptance">Notify client of acceptance</button>':''}${canEdit()&&o?.mode?'<button data-qw-email="order">Email order document</button>':''}${canEdit()&&o?.mode&&!o.invoice_id?'<button data-qw-change>Change order details</button>':''}</div></details>`+history();const form=$('form');if(form){form.onsubmit=submit;form.elements.mode?.addEventListener('change',()=>{const section=$('[data-lpo-fields]');if(section){section.hidden=form.elements.mode.value!=='client_lpo';section.querySelectorAll('input,select').forEach(el=>el.disabled=section.hidden);}});form.elements.mode?.dispatchEvent(new Event('change'));}}
function prepareForm(){return `<h3>Prepare invoice · order details</h3><form data-qw-form="prepare"><label><input type="checkbox" name="requiresLpo" ${data.order?.requires_lpo?'checked':''}> This client requires an LPO</label><label class="field">Purchasing document<select name="mode"><option value="client_lpo">Upload client LPO</option><option value="prepared_po">Prepare PO for client approval</option><option value="confirmation">Use order confirmation (no LPO)</option></select></label><div data-lpo-fields>${field('file','Client LPO','file','','required accept="application/pdf,image/*"')}<div class="qw-grid">${field('number','Client LPO number','text','','required maxlength="100"')}${field('date','LPO date','date',today(),'required')}${field('amount','LPO value','number',data.quote.amount,'required step="0.01" min="0.01"')}${field('currency','Currency','text',data.quote.currency||'MWK','required pattern="[A-Z]{3}"')}</div><label><input type="checkbox" name="scopeConfirmed" required> I checked that the LPO services, quantities and terms match the accepted quotation.</label></div><div class="dialog-actions"><button class="primary-button">Save order details</button></div></form>`;}
async function submit(e){e.preventDefault();if(busy)return;const f=e.currentTarget,token=epoch,action=f.dataset.qwForm,values=Object.fromEntries(new FormData(f));values.confirmed=!!f.elements.confirmed?.checked;values.requiresLpo=!!f.elements.requiresLpo?.checked;values.scopeConfirmed=!!f.elements.scopeConfirmed?.checked;busy=true;f.querySelectorAll('button').forEach(b=>b.disabled=true);$('.qw-error').textContent='';$('[data-qw-progress]').textContent='Saving…';try{
 const file=f.elements.file?.files[0]||f.elements.evidence?.files[0];if(file){const fingerprint=[file.name,file.size,file.lastModified].join(':');if(f.dataset.fileFingerprint!==fingerprint){const uploaded=await api().uploadFile(file,'quote_order',data.quote.id);f.dataset.filePath=uploaded.path;f.dataset.fileFingerprint=fingerprint;}values[action==='prepare'?'path':'evidence']=f.dataset.filePath;}
 const result=await api().quoteOrder(data.quote.id,action,data.quote,values,data.order?.version||0);if(token!==epoch)return;data=result;render();
}catch(error){if(token===epoch){$('.qw-error').textContent=error.message;$('[data-qw-progress]').textContent='';}}finally{busy=false;if(token===epoch)f.querySelectorAll('button').forEach(b=>b.disabled=false);}}
async function open(id){const token=++epoch;data=null;dialog.innerHTML='<h2>Quotation workflow</h2><p>Loading…</p><button data-qw-close>Close</button>';if(!dialog.open)dialog.showModal();try{const result=await api().quoteOrder(id,'read');if(token!==epoch)return;data=result;render();}catch(error){if(token===epoch)dialog.innerHTML=`<h2>Quotation workflow</h2><p class="qw-error">${esc(error.message)}</p><button data-qw-close>Close</button>`;}}
async function preview(){const token=epoch;const r=CageOrderDocument.documentRecord(data);const logo=await fetch('./cage-logo-new.png');if(!logo.ok)throw new Error('CAGE logo could not load');const bytes=await CagePDF.createDocumentPDF(PDFLib,r,'order',await logo.arrayBuffer(),new Date(data.order.order_data.preparedAt));if(token!==epoch)return;if(url)URL.revokeObjectURL(url);url=URL.createObjectURL(new Blob([bytes],{type:'application/pdf'}));dialog.innerHTML=header()+`<a class="primary-button" href="${url}" download="${esc(r.number)}.pdf">Download PDF</a><iframe src="${url}" title="Order document"></iframe><button data-qw-back>Back</button><p class="qw-error" role="alert"></p>`;}
function email(kind){const pending=data.deliveries.find(d=>d.kind===kind&&d.version===(data.order?.version||0)&&!d.confirmed);const a=data.order?.acceptance||data.quote.clientResponse;const intro=a?.source==='staff'?`As agreed with ${a.contact} via ${a.method} on ${a.date}, we have recorded your acceptance of quotation ${data.quote.number} for ${data.quote.currency||'MWK'} ${Number(data.quote.amount).toLocaleString()}. Please let us know if this does not reflect your understanding.`:`Thank you for accepting quotation ${data.quote.number}.`;
const message=pending?.message||(kind==='acceptance'?intro:data.order.mode==='prepared_po'&&!data.order.po_approval?'Please review the attached purchase order prepared by CAGE from your accepted quotation. Please reply to confirm your approval or tell us what needs changing. It remains a draft until your approval is recorded.':'Please find the attached order document based on your accepted quotation.');
dialog.innerHTML=header()+`<h3>Review client notification</h3><form data-qw-email-form>${field('recipient','Client email','email',pending?.recipient||data.quote.recipient||'','required maxlength="254"')}<label class="field">Message<textarea name="message" rows="6" maxlength="5000" required>${esc(message)}</textarea></label><p class="qw-muted">${kind==='order'?'The order PDF will be attached.':'This email confirms the recorded agreement.'} Check the address and wording before sending.</p><div class="dialog-actions"><button class="primary-button">Send email</button><button type="button" data-qw-back>Back</button></div></form><p class="qw-error" role="alert"></p><p role="status" data-qw-progress></p>`;
$('form').onsubmit=async e=>{e.preventDefault();if(busy)return;const f=e.currentTarget,token=epoch;busy=true;const v=Object.fromEntries(new FormData(f));f.querySelectorAll('button,input,textarea').forEach(x=>x.disabled=true);$('[data-qw-progress]').textContent='Sending…';try{await api().sendOrderDocument({qid:data.quote.id,version:data.order?.version||0,kind,...v});if(token!==epoch)return;busy=false;await open(data.quote.id);$('[data-qw-progress]').textContent='Email accepted by the provider.';}catch(err){if(token===epoch){$('.qw-error').textContent=err.message;$('[data-qw-progress]').textContent='';}}finally{busy=false;f.querySelectorAll('button,input,textarea').forEach(x=>x.disabled=false);}};}
dialog.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b||busy)return;try{if(b.hasAttribute('data-qw-close'))close();else if(b.hasAttribute('data-qw-back'))render();else if(b.hasAttribute('data-qw-change')){dialog.innerHTML=header()+prepareForm()+'<p class="qw-error" role="alert"></p><p data-qw-progress role="status"></p>';const f=$('form');f.onsubmit=submit;f.elements.mode.onchange=()=>{const s=$('[data-lpo-fields]');s.hidden=f.elements.mode.value!=='client_lpo';s.querySelectorAll('input').forEach(x=>x.disabled=s.hidden);};f.elements.mode.onchange();}else if(b.hasAttribute('data-qw-preview'))await preview();else if(b.dataset.qwEmail)email(b.dataset.qwEmail);else if(b.dataset.qwFile)await api().openFile(b.dataset.qwFile);else if(b.dataset.qwReceipt)await window.CAGE_RECEIPTS.open(b.dataset.qwReceipt);else if(b.hasAttribute('data-qw-quote'))await window.CAGE_DOCUMENTS.preview(data.quote,'quote');else if(b.hasAttribute('data-qw-invoice')){const inv=data.invoice;close();if(inv.status==='Draft')openSendDocument('invoice',inv.id);else window.CAGE_DOCUMENTS.preview(inv,'invoice');}else if(b.hasAttribute('data-qw-pay')){const id=data.invoice.id;close();await window.CAGE_PAYMENTS.open(id);}}catch(err){if($('.qw-error'))$('.qw-error').textContent=err.message;else app().showToast(err.message);}});
function decorate(){document.querySelectorAll('[data-send-document][data-document-id]').forEach(send=>{if(send.closest('.qw-actions')||send.closest('#send-dialog'))return;const type=send.dataset.sendDocument;if(!['quote','invoice'].includes(type))return;const r=app()?.getState()?.[type==='quote'?'quotes':'invoices']?.find(x=>x.id===send.dataset.documentId);if(!r)return;const parent=send.parentElement;if(!['TD','DIV'].includes(parent.tagName))return;const wrapper=document.createElement('div');wrapper.className='qw-actions';const main=document.createElement('button');main.type='button';main.className='document-action qw-main';const details=document.createElement('details');details.className='qw-more';details.innerHTML='<summary aria-label="More document actions">⋯</summary><div class="qw-menu"></div>';const menu=details.querySelector('div');send.before(wrapper);wrapper.append(main,details);
 const invoice=type==='quote'?app().getState().invoices.find(i=>i.quoteId===r.id):null;main.textContent=type==='quote'?(invoice?'View workflow':r.status==='Accepted'?'Prepare invoice':r.sentAt?'Record acceptance':'Send quotation'):(r.status==='Paid'?'View receipt':r.sentAt?'Record payment':'Send invoice');
 main.onclick=async()=>{try{if(type==='quote'){if(!r.sentAt&&r.status!=='Accepted'){send.click();return;}await open(r.id);}else if(r.status==='Paid'){const rows=(await api().managedRecords('invoice_payments')).filter(p=>p.invoice_id===r.id).sort((a,b)=>String(b.created_at).localeCompare(String(a.created_at)));if(!rows.length)throw new Error('No recorded payments found for this invoice.');await window.CAGE_RECEIPTS.open(rows[0].id);}else if(r.sentAt)await window.CAGE_PAYMENTS.open(r.id);else send.click();}catch(err){app().showToast(err.message);}};
 for(const b of [...parent.children])if(b!==wrapper&&(b.matches('button[data-send-document],button[data-edit-finance],button[data-delete-finance],button[data-delivery-history]')))menu.append(b);
 if(type==='quote'){const b=document.createElement('button');b.textContent='Workflow / record acceptance';b.onclick=()=>open(r.id);menu.append(b);}const pdf=document.createElement('button');pdf.textContent='View / download PDF';pdf.onclick=()=>window.CAGE_DOCUMENTS.preview(r,type).catch(e=>app().showToast(e.message));menu.append(pdf);main.hidden=!canEdit()&&r.status!=='Paid';});}
let scheduled=false;new MutationObserver(()=>{if(scheduled)return;scheduled=true;requestAnimationFrame(()=>{scheduled=false;decorate();});}).observe(document.body,{childList:true,subtree:true});
document.addEventListener('click',e=>{const b=e.target.closest('[data-view-document]');if(!b)return;const type=b.dataset.viewDocument,id=b.dataset.recordId;if(type==='quote'){e.preventDefault();e.stopImmediatePropagation();open(id);}else if(type==='invoice'){const r=app().getState().invoices.find(x=>x.id===id);if(r?.quoteId){e.preventDefault();e.stopImmediatePropagation();open(r.quoteId);}}},true);
window.CAGE_ORDERS={open};decorate();
})();
